class Cache
  def initialize(packer: nil)
    @packer = packer
    @entries = {}
    @order = []
  end

  def write(key, payload, stale: false)
    entry = {
      payload: payload,
      stale: stale,
      order: @order.length
    }
    @entries[key] = entry
    @order << key
  end

  def read(key)
    return nil unless @entries.key?(key)
    entry = @entries[key]
    return nil if entry[:stale]
    payload = entry[:payload]
    if @packer
      payload = @packer.load(payload)
    end
    payload
  end

  def sweep
    @order.each do |key|
      next unless @entries.key?(key)
      entry = @entries[key]
      payload = entry[:payload]
      if @packer
        payload = @packer.load(payload)
      end
      if entry[:stale]
        @entries.delete(key)
      end
    end
  end
end
