class OpenRecord
  def initialize(**attrs)
    @attributes = {}
    attrs.each do |key, value|
      @attributes[key] = value
    end
  end

  def method_missing(method_name, *args)
    # Handle getter methods (e.g., record.name)
    if args.empty? && method_name.to_s.end_with?('=') == false
      attr_name = method_name
      if @attributes.key?(attr_name)
        return @attributes[attr_name]
      end
    end

    # Handle setter methods (e.g., record.name = value)
    if method_name.to_s.end_with?('=')
      attr_name = method_name.to_s[0..-3].to_sym
      if args.length == 1
        @attributes[attr_name] = args.first
        return args.first
      end
    end

    super
  end

  def respond_to_missing?(method_name, include_private = false)
    if method_name.to_s.end_with?('=')
      attr_name = method_name.to_s[0..-3].to_sym
      return true
    end
    if @attributes.key?(method_name)
      return true
    end
    false
  end

  def respond_to?(method_name, include_private = false)
    return true if respond_to_missing?(method_name, include_private)
    super
  end
end
