class Cache
  def initialize(packer: nil)
    @packer = packer
    @store = {} # key -> payload (already packed if packer is used)
  end

  def write(key, payload, stale: false)
    if @packer
      @store[key] = { packed_payload: @packer.dump(payload), stale: stale }
    else
      @store[key] = { packed_payload: payload, stale: stale }
    end
  end

  def read(key)
    entry = @store[key]
    return nil if entry.nil?

    if entry[:stale]
      @store.delete(key)
      return nil
    end

    if @packer
      @packer.load(entry[:packed_payload])
    else
      entry[:packed_payload]
    end
  end

  def sweep
    @store.each_key do |key|
      entry = @store[key]
      if entry[:stale]
        @store.delete(key)
      end
    end
  end
end
