class OpenRecord
  def initialize(**attrs)
    @attributes = {}
    attrs.each do |key, value|
      @attributes[key] = value
      define_attribute_accessor(key)
    end
  end

  def method_missing(method_name, *args, &block)
    if method_name.to_s.end_with?('=')
      attr_name = method_name.to_s.chomp('=')
      if args.length == 1
        @attributes[attr_name.to_sym] = args.first
        define_attribute_accessor(attr_name)
        return
      end
    else
      if @attributes.key?(method_name)
        return @attributes[method_name]
      end
    end
    super
  end

  def respond_to_missing?(method_name, include_private = false)
    if method_name.to_s.end_with?('=')
      attr_name = method_name.to_s.chomp('=')
      # An assignment method is considered responsive if we can set it
      # (which is always true for OpenRecord)
      true
    else
      @attributes.key?(method_name)
    end
  end

  private

  def define_attribute_accessor(name)
    name_sym = name.to_sym
    # Only define if not already defined
    return if self.class.instance_methods(false).include?(name_sym)
    return if self.class.instance_methods(false).include?("#{name_sym}=".to_sym)

    self.class.define_method(name_sym) do
      @attributes[name_sym]
    end

    self.class.define_method("#{name_sym}=".to_sym) do |value|
      @attributes[name_sym] = value
    end
  end
end
